package org.brightstats.desktop;
import java.util.*;
import javafx.geometry.Insets;
import javafx.scene.chart.*;
import javafx.scene.control.*;
import javafx.scene.layout.VBox;
import org.brightstats.stats.*;
final class PolynomialPlots {
    private PolynomialPlots(){}
    static void add(TabPane tabs,NonlinearPls.ScoreFit fit,List<NonlinearPls.CurvePoint> points,List<NonlinearPls.Effect> effects,Bootstrap.Result bootstrap,boolean raw){
        VBox panel=new VBox(12);panel.setPadding(new Insets(12));Label note=new Label((raw?"Original observed-variable units. ":"Unit-variance component-score units. ")+"Curves hold other equation parents at the specified probe values. Derivatives are local associations; selected bootstrap bounds are pointwise, not simultaneous.");note.setWrapText(true);panel.getChildren().add(note);
        if(!points.isEmpty()){var first=points.getFirst();NumberAxis x=new NumberAxis(),y=new NumberAxis();x.setForceZeroInRange(false);y.setForceZeroInRange(false);x.setLabel(fit.names().get(first.source())+(raw?" (original units)":" (component score)"));y.setLabel(fit.names().get(first.target())+(raw?" (conditional fitted value)":" (fitted score)"));LineChart<Number,Number> chart=new LineChart<>(x,y);chart.setTitle("Polynomial conditional equation mean");chart.setAnimated(false);chart.setCreateSymbols(false);chart.setMinHeight(440);Map<Integer,Bootstrap.Estimate> intervals=new HashMap<>();if(bootstrap!=null)for(var estimate:bootstrap.estimates())if(estimate.parameter().family().equals(raw?"Raw-unit conditional fitted outcome":"Conditional fitted outcome"))intervals.put(estimate.parameter().column(),estimate);Map<String,List<Integer>> groups=new LinkedHashMap<>();for(int index=0;index<points.size();index++)groups.computeIfAbsent(points.get(index).probe(),key->new ArrayList<>()).add(index);boolean missing=false;for(var group:groups.entrySet()){var middle=new XYChart.Series<Number,Number>();middle.setName(group.getKey());var low=new XYChart.Series<Number,Number>();low.setName(group.getKey()+" pointwise lower");var high=new XYChart.Series<Number,Number>();high.setName(group.getKey()+" pointwise upper");boolean available=bootstrap!=null;for(int index:group.getValue()){var point=points.get(index);middle.getData().add(new XYChart.Data<>(point.x(),point.value()));var interval=intervals.get(index);if(interval==null||!Double.isFinite(interval.lower())||!Double.isFinite(interval.upper()))available=false;else{low.getData().add(new XYChart.Data<>(point.x(),interval.lower()));high.getData().add(new XYChart.Data<>(point.x(),interval.upper()));}}chart.getData().add(middle);if(available){chart.getData().add(low);chart.getData().add(high);}else if(bootstrap!=null)missing=true;}panel.getChildren().add(chart);if(missing)panel.getChildren().add(UiAppearance.label("Unavailable bound series are omitted in full; missing intervals are never drawn as zero."));}
        if(!effects.isEmpty()){int source=fit.specification().grid()==null?effects.getFirst().source():fit.specification().grid().source(),target=fit.specification().grid()==null?effects.getFirst().target():fit.specification().grid().target();CategoryAxis x=new CategoryAxis();NumberAxis y=new NumberAxis();x.setLabel("Probe");y.setLabel(raw?"Raw-unit local derivative":"Component-score local derivative");BarChart<String,Number> chart=new BarChart<>(x,y);chart.setTitle(fit.names().get(source)+" to "+fit.names().get(target));chart.setAnimated(false);chart.setMinHeight(400);Map<String,XYChart.Series<String,Number>> groups=new LinkedHashMap<>();for(var effect:effects)if(effect.source()==source&&effect.target()==target&&!effect.family().equals("Specific indirect derivative")){var series=groups.computeIfAbsent(effect.family(),key->{var result=new XYChart.Series<String,Number>();result.setName(key);return result;});series.getData().add(new XYChart.Data<>(effect.probe(),effect.value()));}chart.getData().addAll(groups.values());panel.getChildren().add(chart);}
        Tab tab=new Tab("Polynomial plots",new ScrollPane(panel));tab.setClosable(false);tabs.getTabs().add(tab);
    }
}
